```json
{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Num recipiente isolado, todo o calor que a água quente perde é recebido pelo gelo. O final desejado é só água a 0 °C, sem gelo sobrando. Então o gelo faz duas coisas: esquenta de −20 °C até 0 °C e depois derrete a 0 °C. A água original esfria de 20 °C até 0 °C. A massa final de água é a água original mais o gelo que derreteu.",
      "motivo": "Frases mais curtas e sem ambiguidade; deixa claro o que é calor perdido e recebido."
    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "Q = m × c × Δθ (calor que muda a temperatura)",
        "Q = m × L (calor que muda o estado físico, com temperatura fixa)",
        "calor cedido pela água = calor recebido pelo gelo"
      ],
      "motivo": "Remove a forma 'Q cedido + Q recebido = 0', que mistura sinais e confunde; fica só a igualdade usada nos passos."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["Q", "quantidade de calor, medida em cal (caloria)"],
        ["m", "massa, em gramas"],
        ["c", "calor específico: calor para variar 1 °C em 1 g da substância"],
        ["L", "calor latente: calor para mudar de fase 1 g, sem mudar a temperatura"],
        ["Δθ", "variação de temperatura: temperatura final menos a inicial (aqui usamos o valor positivo)"],
        ["equilíbrio térmico", "momento em que tudo fica na mesma temperatura e não há mais troca de calor"]
      ],
      "motivo": "Inclui m e 'equilíbrio térmico', termos usados na resolução e não explicados."
    },
    {
      "campo": "resolucao.pista",
      "depois": "O objetivo é terminar tudo a 0 °C, sem gelo sobrando. Pense: quanto calor a água tem para dar ao esfriar até 0 °C? E quanto cada grama de gelo precisa receber para virar água a 0 °C?",
      "motivo": "Pista orienta as duas perguntas-chave sem entregar números."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "m × 90 = 9 000 → m = 100 g",
      "motivo": "Cada passo mostra o resultado na linha e cabe em ~30 caracteres."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "Cada grama de gelo consome 10 + 80 = 90 cal no total. A água só tem 9 000 cal para dar. Logo m = 9 000 ÷ 90 = 100 g de gelo.",
      "motivo": "Explica de onde vem o 90 e separa a conta do porquê."
    },
    {
      "campo": "resolucao.erradas.A",
      "depois": "Quem marcou A achou só 75 g de gelo. Esse gelo consome 75 × 90 = 6 750 cal, e a água ainda teria calor sobrando (9 000 cal). A mistura terminaria acima de 0 °C. Faltou conferir se o calor cedido pela água é todo gasto.",
      "motivo": "Diz o que faltou no raciocínio de quem marcou A."
    },
    {
      "campo": "resolucao.erradas.B",
      "depois": "Quem marcou B usou 125 g de gelo. Isso pede 125 × 90 = 11 250 cal, mais que as 9 000 cal da água. Sobraria gelo sem derreter. Faltou comparar o calor que o gelo pede com o que a água tem.",
      "motivo": "Mostra o erro de raciocínio, não só a conta."
    },
    {
      "campo": "resolucao.erradas.C",
      "depois": "Quem marcou C usou 150 g de gelo. Isso pede 150 × 90 = 13 500 cal, mas a água só cede 9 000 cal. O gelo não derreteria todo. Faltou testar se o calor disponível bastava.",
      "motivo": "Indica o que faltou verificar."
    },
    {
      "campo": "resolucao.erradas.E",
      "depois": "Quem marcou E usou 175 g de gelo. Isso pede 175 × 90 = 15 750 cal, bem acima das 9 000 cal cedidas. Sobraria muito gelo. Faltou achar a massa de gelo pelo balanço de calor, em vez de escolher um valor.",
      "motivo": "Indica o que faltou no raciocínio."
    },
    {
      "campo": "resolucao.quadro[6]",
      "depois": {
        "linha": "m = 9 000 ÷ 90",
        "nota": "O 90 passa dividindo para o outro lado",
        "mov": [
          {
            "termo": "90",
            "de": "esquerda",
            "para": "direita",
            "vira": "÷ 90",
            "como": "passa dividindo"
          }
        ]
      },
      "motivo": "O 90 passa para o lado direito dividindo; 'denominador' não descrevia bem o movimento."
    }
  ],
  "didatica_alertas": [
    "Classificação: a questão trata de calorimetria (tema F06), mas o cabeçalho informa F08/F08.3 (óptica, espelhos esféricos); o JSON usa F06/F06.4. Corrigir a classificação no banco.",
    "O campo nivel do JSON é 4 e o cabeçalho informa 5; conferir."
  ],
  "didatica_ok": true
}
